-- ساخت پایگاه داده و جدول‌های نمونهٔ فروشگاه
CREATE DATABASE shop;
\c shop

CREATE TABLE customers (
  id          BIGSERIAL    PRIMARY KEY,
  name        TEXT         NOT NULL,
  email       TEXT         UNIQUE,
  city        TEXT,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE products (
  id       BIGSERIAL       PRIMARY KEY,
  title    TEXT            NOT NULL,
  category TEXT            NOT NULL,
  price    NUMERIC(12,2)   NOT NULL CHECK (price >= 0)
);

CREATE TABLE orders (
  id          BIGSERIAL     PRIMARY KEY,
  customer_id BIGINT        NOT NULL REFERENCES customers(id),
  total       NUMERIC(12,2) NOT NULL CHECK (total >= 0),
  created_at  TIMESTAMPTZ   NOT NULL DEFAULT now()
);

-- تطبیق الگو: % هر تعداد کاراکتر، _ یک کاراکتر
SELECT title FROM products
WHERE title ILIKE '%laptop%';

-- عضویت در مجموعه
SELECT name FROM customers
WHERE city IN ('Tehran', 'Isfahan', 'Tabriz');

-- بازهٔ بسته (شامل دو سر)
SELECT title FROM products
WHERE price BETWEEN 100 AND 300;

-- ترکیب شرط‌ها با اولویت صریح
SELECT title FROM products
WHERE (category = 'gear' AND price < 200)
   OR category = 'laptop';

-- غیرنرمال: همه چیز در یک جدول
-- orders_raw(id, customer_name, customer_email, product_titles, city)
-- product_titles = 'Laptop,Mouse'  <- نقض 1NF

-- 3NF: جدول‌های جدا با روابط
CREATE TABLE cities (
  id   BIGSERIAL PRIMARY KEY,
  name TEXT UNIQUE NOT NULL
);

CREATE TABLE customers (
  id    BIGSERIAL PRIMARY KEY,
  name  TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL,
  city_id INT REFERENCES cities(id)
);

CREATE TABLE order_items (
  order_id   BIGINT REFERENCES orders(id) ON DELETE CASCADE,
  product_id BIGINT REFERENCES products(id),
  quantity   INT NOT NULL CHECK (quantity > 0),
  PRIMARY KEY (order_id, product_id)
);

-- ایندکس ساده
CREATE INDEX idx_orders_customer_id ON orders (customer_id);

-- ایندکس ترکیبی: ترتیب ستون‌ها حیاتی است
CREATE INDEX idx_orders_cust_created
  ON orders (customer_id, created_at DESC);

-- ایندکس جزئی: کوچک‌تر و سریع‌تر برای یک زیرمجموعه
CREATE INDEX idx_orders_pending
  ON orders (created_at)
  WHERE status = 'pending';

-- ایندکس روی عبارت
CREATE INDEX idx_orders_month
  ON orders (date_trunc('month', created_at));

BEGIN;

UPDATE accounts SET balance = balance - 100
WHERE id = 1 AND balance >= 100;

UPDATE accounts SET balance = balance + 100
WHERE id = 2;

COMMIT;   -- یا ROLLBACK در مسیر خطا

CREATE VIEW v_customer_orders AS
SELECT c.id, c.name, o.id AS order_id, o.total, o.created_at
FROM customers c
JOIN orders o ON o.customer_id = c.id;

-- استفاده مثل یک جدول
SELECT name, SUM(total) AS lifetime_value
FROM v_customer_orders
GROUP BY id, name;

-- ویو به‌عنوان لایهٔ امنیتی: بدون اطلاعات حساس
CREATE VIEW v_orders_public AS
SELECT order_id, total, created_at FROM v_customer_orders;

GRANT SELECT ON v_orders_public TO analyst_role;

CREATE MATERIALIZED VIEW mv_daily_revenue AS
SELECT date_trunc('day', created_at) AS day,
       COUNT(*)    AS orders_count,
       SUM(total)  AS revenue
FROM orders
GROUP BY 1;

CREATE UNIQUE INDEX ON mv_daily_revenue (day);

-- تازه‌سازی بدون قطع خوانندگان
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily_revenue;

-- مهاجرت رفت
ALTER TABLE users ADD COLUMN phone TEXT;

-- مهاجرت برگشت (برای rollback)
-- ALTER TABLE users DROP COLUMN phone;

-- ایندکس‌های بلااستفاده (PostgreSQL)
SELECT relname, indexrelname, idx_scan
FROM pg_stat_user_indexes
WHERE idx_scan = 0 AND relname NOT LIKE 'pg_%';

-- بازپیکربندی فضا و آمار
VACUUM ANALYZE orders;
